use crate::ast::PullSpec;
#[derive(Debug,Clone,PartialEq)]
pub struct PullPlan{pub resource:String,pub url:String,pub kind:&'static str,pub revision:Option<String>,pub checksum:Option<String>,pub build_system:Option<String>}
pub fn validate_pull(s:&PullSpec)->Result<PullPlan,String>{let(url,kind)=if let Some(v)=&s.source{(v,"source")}else if let Some(v)=&s.binary{(v,"binary")}else{return Err("pull needs a source or binary URL".into())};if !(url.starts_with("https://")||(kind=="source"&&url.starts_with("git@"))){return Err("pull URLs must use HTTPS (SSH Git URLs are source-only)".into())}if kind=="binary"{let d=s.checksum.as_deref().ok_or("binary pulls require SHA256")?.strip_prefix("SHA256:").unwrap_or(s.checksum.as_deref().unwrap());if d.len()!=64||!d.chars().all(|c|c.is_ascii_hexdigit()){return Err("checksum must be a 64-character SHA256 hex digest".into())}}if s.build.is_some()&&kind!="source"{return Err("build is only valid for source pulls".into())}Ok(PullPlan{resource:s.name.clone(),url:url.clone(),kind,revision:s.revision.clone(),checksum:s.checksum.clone(),build_system:s.build.clone()})}
pub fn describe_pull(s:&PullSpec)->Result<String,String>{let p=validate_pull(s)?;let mut o=format!("Builgine pull plan: {}\n  kind: {}\n  url: {}\n",p.resource,p.kind,p.url);if let Some(v)=p.revision{o.push_str(&format!("  revision: {v}\n"))}if let Some(v)=p.checksum{o.push_str(&format!("  checksum: {v}\n"))}if let Some(v)=p.build_system{o.push_str(&format!("  build system: {v}\n"))}o.push_str("  status: validated; fetch/build backend is planned, not enabled yet\n");Ok(o)}
